func TestWalkError(t *testing.T) {
	e1 := errors.New("err1")
	e2 := errors.New("err2")
	e3 := errors.New("err3")

	t.Run("nil error", func(t *testing.T) {
		var visited []error
		walkError(nil, func(err error) {
			visited = append(visited, err)
		})
		if len(visited) != 0 {
			t.Fatalf("expected 0 visited errors, got %d", len(visited))
		}
	})

	t.Run("fmt.Errorf %w chain", func(t *testing.T) {
		wrapped := fmt.Errorf("outer: %w", fmt.Errorf("inner: %w", e1))
		var visited []error
		walkError(wrapped, func(err error) {
			visited = append(visited, err)
		})
		if len(visited) != 3 {
			t.Fatalf("expected 3 visited errors, got %d", len(visited))
		}
		if visited[2] != e1 {
			t.Errorf("expected leaf error %v, got %v", e1, visited[2])
		}
	})

	t.Run("errors.Join", func(t *testing.T) {
		joined := fmt.Errorf("outer: %w", errors.Join(e1, e2))
		var visited []error
		walkError(joined, func(err error) {
			visited = append(visited, err)
		})
		if len(visited) != 4 {
			t.Fatalf("expected 4 visited errors, got %d", len(visited))
		}
		if visited[2] != e1 || visited[3] != e2 {
			t.Errorf("expected leaf errors %v and %v, got %v and %v", e1, e2, visited[2], visited[3])
		}
	})

	t.Run("WrappedErrors (multierror.Error)", func(t *testing.T) {
		me := &multiErr{errs: []error{e1, fmt.Errorf("wrapped: %w", e2), e3}}
		var visited []error
		walkError(me, func(err error) {
			visited = append(visited, err)
		})
		if len(visited) != 5 {
			t.Fatalf("expected 5 visited errors, got %d", len(visited))
		}
		if visited[1] != e1 || visited[3] != e2 || visited[4] != e3 {
			t.Errorf("unexpected visited order: %v", visited)
		}
	})
}

func TestIsRetryableError_UnwrapVariants(t *testing.T) {
	retryable500 := &googleapi.Error{Code: 500}
	nonRetryable400 := &googleapi.Error{Code: 400}

	abortPred := func(err error) (bool, string) {
		if gerr, ok := err.(*googleapi.Error); ok && gerr.Code == 400 {
			return true, "abort on 400"
		}
		return false, ""
	}

	t.Run("fmt.Errorf %w retryable", func(t *testing.T) {
		err := fmt.Errorf("outer: %w", retryable500)
		if !IsRetryableError(err, nil, nil) {
			t.Errorf("expected fmt.Errorf wrapped 500 to be retryable")
		}
	})

	t.Run("errors.Join retryable", func(t *testing.T) {
		err := errors.Join(errors.New("unrelated"), retryable500)
		if !IsRetryableError(err, nil, nil) {
			t.Errorf("expected errors.Join containing 500 to be retryable")
		}
	})

	t.Run("multierror WrappedErrors retryable", func(t *testing.T) {
		err := &multiErr{errs: []error{errors.New("first"), retryable500}}
		if !IsRetryableError(err, nil, nil) {
			t.Errorf("expected multiErr containing 500 in second element to be retryable")
		}
	})

	t.Run("multierror WrappedErrors abortable overrides retryable", func(t *testing.T) {
		err := &multiErr{errs: []error{retryable500, nonRetryable400}}
		if IsRetryableError(err, nil, []RetryErrorPredicateFunc{abortPred}) {
			t.Errorf("expected multiErr containing abortable 400 to not be retryable")
		}
	})
}
